<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Friendship extends Model {protected $fillable=['requester_id','addressee_id','status','accepted_at']; protected function casts():array{return ['accepted_at'=>'datetime'];} public function requester(){return $this->belongsTo(User::class,'requester_id');} public function addressee(){return $this->belongsTo(User::class,'addressee_id');}}
